#!/bin/sh
# ============================================================================
# dsh-ios  +ios7 —— 预装官方 QQ Bot 插件 @tencent-connect/dsh-qqbot 0.5.5
#
# 症状：在 iPhone 终端里照 README 装插件，报「退出码 127」/「pnpm not found」，
#       装不上；换了几个插件包都是一样。别人在电脑上正常。
#
# 根因（已核对 dsh 0.2.1-rc.5 源码与插件 install.sh）：
#   dsh 的 `plugin` 子命令把参数原样转发给 pnpm ——
#     lib/plugin-BiveYA7h.js:94  "dsh: pnpm was not found; install pnpm ..."
#   而 127 正是 shell 的 command-not-found。iPhone 越狱环境里没有
#   pnpm / npm / npx / corepack / git，本包又只内置了 node，所以必失败。
#   这跟 node 版本、签名、A11、网络都无关，是设备端缺包管理器。
#
# 修法：完全绕开设备端包管理。把插件及其 32 个运行时依赖直接固化进
#   /var/jb/usr/lib/dsh/node_modules/（纯 JS，无 .node，约 1.2MB）；
#   peer（cordis / dsh-agent / dsh-llm / dsh-session / schemastery /
#   dsh-user-approval）直接复用宿主自带的 0.2.1-rc.5 版本；
#   再把一行 insert 追加到 $DSH_HOME/cordis.patch.yml —— 这是 dsh 原生的
#   home 级用户 patch 层，对所有 profile 生效，等价于官方 plugin add 的效果。
#
# 已在 x86 Linux 按 iOS 目录布局实测：native 档与 A11 实际会落的 nowasm 档
# (--jitless --no-expose-wasm --require fetch-shim.cjs) 都能激活 im-qqbot，
# 0 个 did-not-activate、0 个 error；QQ 网关用 ws 包、扫码用 node:https，
# 都不受零 JIT 档 fetch shim 影响。
#
# 还有一个只有真机才会踩到的坑：dsh 的 ESM resolver 以 **profile 目录**
# ($DSH_HOME/profiles/<name>/) 为基准解析插件包名，而插件实体放在包目录
# $D/node_modules —— 两者不在同一棵祖先链上，真机必然
# ERR_MODULE_NOT_FOUND。构建机上常因目录层级巧合看不出来（假绿灯）。
# 所以本脚本会在 $DSH_HOME/node_modules 建一条解析链路（软链，不动已有目录），
# 这是插件能加载的必要条件，不是可选项。
#
# 用法（iPhone 终端）：
#   sh install-qqbot.sh              安装（幂等，可重复跑）
#   sh install-qqbot.sh --status    查看状态
#   sh install-qqbot.sh --remove    卸载插件、恢复原配置
#
# ！！！装完必须 Ctrl+C 退出当前 dsh，再重新敲 dsh 才会加载插件。
#     刷新网页无效：Cordis 插件树是进程启动时组合的。
# ============================================================================
set -eu

JB=/var/jb
D="$JB/usr/lib/dsh"
NM="$D/node_modules"
NODE="$D/bin/node"
BIN="$NM/@deepseek-ai/dsh/lib/bin.js"
ETCD="$JB/etc/dsh"
ENVF="$ETCD/dsh.env"
QENV="$ETCD/qqbot.env"
QPATCH="$ETCD/qqbot.patch.yml"
LINK="$D/cordis.patch.yml"
MARK="$ETCD/.qqbot-installed"
HOME_DSH="${DSH_HOME:-$JB/var/mobile/.dsh}"
UPATCH="$HOME_DSH/cordis.patch.yml"

MODE=install
case "${1:-}" in
    --remove) MODE=remove ;;
    --status) MODE=status ;;
    "")      ;;
    *) echo "用法: sh install-qqbot.sh [--status|--remove]" >&2; exit 2 ;;
esac

# ---- 门禁 ----
if [ ! -L "$JB" ] || [ ! -x "$NODE" ] || [ ! -f "$BIN" ]; then
    echo "[FAIL] 越狱未激活，或 dsh-ios 的 .deb 没装（找不到 $BIN）。" >&2
    exit 1
fi

# ---- --status ----
if [ "$MODE" = status ]; then
    if [ -f "$NM/@tencent-connect/dsh-qqbot/lib/index.js" ]; then S1=已安装; else S1=缺失; fi
    if [ -f "$QPATCH" ]; then S2=已安装; else S2=缺失; fi
    if grep -q 'id: im-qqbot' "$UPATCH" 2>/dev/null; then S3=已挂载; else S3=未挂载; fi
    echo "插件文件 : $S1"
    echo "patch    : $S2"
    echo "用户层   : $S3"
    echo "凭据文件 : $QENV（AppID/Secret 是否填好请自己看这个文件）"
    if [ -e "$HOME_DSH/node_modules/@tencent-connect/dsh-qqbot/lib/index.js" ]; then S4=通; else S4=断; fi
    echo "解析链路 : $S4"
    exit 0
fi

# ---- --remove ----
if [ "$MODE" = remove ]; then
    if [ -f "$ENVF.pre-qqbot.bak" ]; then cp "$ENVF.pre-qqbot.bak" "$ENVF"; rm -f "$ENVF.pre-qqbot.bak"; echo "[ ok ] 已恢复 dsh.env"; fi
    if [ -f "$UPATCH.pre-qqbot.bak" ]; then
        cp "$UPATCH.pre-qqbot.bak" "$UPATCH"; rm -f "$UPATCH.pre-qqbot.bak"; echo "[ ok ] 已恢复 cordis.patch.yml"
    else
        rm -f "$UPATCH"; echo "[ ok ] 已删除自动生成的 cordis.patch.yml"
    fi
    if [ -L "$LINK" ]; then rm -f "$LINK"; fi
    NMHOME="$HOME_DSH/node_modules"
    if [ -L "$NMHOME" ]; then
        T=$(readlink "$NMHOME" 2>/dev/null || true)
        if [ "$T" = "$NM" ]; then rm -f "$NMHOME"; fi
    fi
    if [ -L "$NMHOME/@tencent-connect/dsh-qqbot" ]; then rm -f "$NMHOME/@tencent-connect/dsh-qqbot"; fi
    rm -rf "$NM/@tencent-connect/dsh-qqbot"
    rm -rf "$NM/@tencent-connect/qqbot-connector"
    rm -rf "$NM/@tencent-connect/qqbot-nodejs"
    rm -rf "$NM/ansi-regex"
    rm -rf "$NM/ansi-styles"
    rm -rf "$NM/camelcase"
    rm -rf "$NM/cliui"
    rm -rf "$NM/color-convert"
    rm -rf "$NM/color-name"
    rm -rf "$NM/decamelize"
    rm -rf "$NM/dijkstrajs"
    rm -rf "$NM/emoji-regex"
    rm -rf "$NM/find-up"
    rm -rf "$NM/get-caller-file"
    rm -rf "$NM/is-fullwidth-code-point"
    rm -rf "$NM/locate-path"
    rm -rf "$NM/p-locate"
    rm -rf "$NM/p-try"
    rm -rf "$NM/path-exists"
    rm -rf "$NM/pngjs"
    rm -rf "$NM/qrcode"
    rm -rf "$NM/qrcode-terminal"
    rm -rf "$NM/require-directory"
    rm -rf "$NM/require-main-filename"
    rm -rf "$NM/set-blocking"
    rm -rf "$NM/string-width"
    rm -rf "$NM/strip-ansi"
    rm -rf "$NM/which-module"
    rm -rf "$NM/wrap-ansi"
    rm -rf "$NM/y18n"
    rm -rf "$NM/yargs"
    rm -rf "$NM/yargs-parser"
    rm -f "$QPATCH" "$MARK"
    echo "[ ok ] QQ Bot 插件已移除。qqbot.env（凭据）保留，可手动删除。"
    echo "       重启 dsh 生效：Ctrl+C 后重新敲 dsh。"
    exit 0
fi

# ---- install ----
echo "==> 预装 @tencent-connect/dsh-qqbot 0.5.5（无需重传 deb）"

# 只备份一次，供 --remove 精确回滚
if [ ! -f "$ENVF.pre-qqbot.bak" ]; then cp "$ENVF" "$ENVF.pre-qqbot.bak" 2>/dev/null || true; fi
# 只备份「不含插件」的原版：否则二次安装会把已含 im-qqbot 的版本存成备份，
# --remove 恢复后等于没删干净。
if [ -f "$UPATCH" ] && [ ! -f "$UPATCH.pre-qqbot.bak" ] \
   && ! grep -q 'id: im-qqbot' "$UPATCH" 2>/dev/null; then
    cp "$UPATCH" "$UPATCH.pre-qqbot.bak" 2>/dev/null || true
fi
mkdir -p "$HOME_DSH" "$ETCD" 2>/dev/null || true

# 1) 目录
mkdir -p "$NM/@tencent-connect/dsh-qqbot" "$NM/@tencent-connect/dsh-qqbot/assets/icons" "$NM/@tencent-connect/dsh-qqbot/lib" "$NM/@tencent-connect/dsh-qqbot/lib/commands" "$NM/@tencent-connect/dsh-qqbot/lib/features" "$NM/@tencent-connect/dsh-qqbot/lib/gateway" "$NM/@tencent-connect/dsh-qqbot/lib/host" "$NM/@tencent-connect/dsh-qqbot/lib/media" "$NM/@tencent-connect/dsh-qqbot/lib/middleware" "$NM/@tencent-connect/dsh-qqbot/lib/model" "$NM/@tencent-connect/dsh-qqbot/lib/session" "$NM/@tencent-connect/dsh-qqbot/lib/setup"
mkdir -p "$NM/@tencent-connect/dsh-qqbot/lib/shared" "$NM/@tencent-connect/dsh-qqbot/lib/transport" "$NM/@tencent-connect/dsh-qqbot/locale" "$NM/@tencent-connect/dsh-qqbot/scripts" "$NM/@tencent-connect/qqbot-connector" "$NM/@tencent-connect/qqbot-connector/dist/cjs" "$NM/@tencent-connect/qqbot-connector/dist/esm" "$NM/@tencent-connect/qqbot-nodejs" "$NM/@tencent-connect/qqbot-nodejs/dist" "$NM/@tencent-connect/qqbot-nodejs/dist/middleware" "$NM/@tencent-connect/qqbot-nodejs/dist/protocol" "$NM/@tencent-connect/qqbot-nodejs/dist/protocol/api"
mkdir -p "$NM/@tencent-connect/qqbot-nodejs/dist/protocol/gateway" "$NM/@tencent-connect/qqbot-nodejs/dist/protocol/transport" "$NM/@tencent-connect/qqbot-nodejs/dist/protocol/utils" "$NM/@tencent-connect/qqbot-nodejs/dist/storage" "$NM/ansi-regex" "$NM/ansi-styles" "$NM/camelcase" "$NM/cliui" "$NM/color-convert" "$NM/color-name" "$NM/decamelize" "$NM/dijkstrajs"
mkdir -p "$NM/emoji-regex" "$NM/emoji-regex/es2015" "$NM/find-up" "$NM/get-caller-file" "$NM/is-fullwidth-code-point" "$NM/locate-path" "$NM/p-locate" "$NM/p-try" "$NM/path-exists" "$NM/pngjs" "$NM/pngjs/lib" "$NM/qrcode"
mkdir -p "$NM/qrcode-terminal" "$NM/qrcode-terminal/bin" "$NM/qrcode-terminal/lib" "$NM/qrcode-terminal/vendor/QRCode" "$NM/qrcode/helper" "$NM/qrcode/lib" "$NM/qrcode/lib/core" "$NM/qrcode/lib/renderer" "$NM/qrcode/lib/renderer/terminal" "$NM/require-directory" "$NM/require-main-filename" "$NM/set-blocking"
mkdir -p "$NM/string-width" "$NM/strip-ansi" "$NM/which-module" "$NM/wrap-ansi" "$NM/y18n" "$NM/yargs" "$NM/yargs-parser" "$NM/yargs-parser/lib" "$NM/yargs/build/lib" "$NM/yargs/locales"

# 2) 插件依赖树（321 个纯文本 JS/JSON 文件，无二进制、无 .node）
cat > "$NM/@tencent-connect/dsh-qqbot/assets/icons/qq_logo.svg" <<'DSHQQBOT_F0_7c1e'
<svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
<path d="M18.3262 10.3168C18.327 10.2893 18.3387 9.82506 18.3387 9.58562C18.3387 5.55264 16.4443 1.5002 11.7858 1.5C7.12723 1.5002 5.23276 5.55264 5.23276 9.58562C5.23276 9.81458 5.24351 10.2491 5.24503 10.3107L5.24518 10.3168L4.30497 12.6751C4.04744 13.3501 3.79317 14.0528 3.60687 14.6554C2.71838 17.529 3.00622 18.7182 3.22537 18.7448C3.69578 18.8019 5.05615 16.5816 5.05615 16.5816C5.05615 17.8673 5.71429 19.5452 7.1393 20.7568C6.60638 20.922 5.95335 21.176 5.53375 21.4874C5.15646 21.7675 5.20345 22.0529 5.27147 22.1682C5.57006 22.6745 10.3937 22.4914 11.7863 22.3338C13.1789 22.4914 18.0025 22.6745 18.3011 22.1682C18.3691 22.0529 18.4161 21.7675 18.0388 21.4874C17.619 21.1759 16.9655 20.9217 16.4324 20.7565C17.8572 19.545 18.5153 17.8672 18.5153 16.5816C18.5153 16.5816 19.8757 18.8019 20.346 18.7448C20.5652 18.7182 20.853 17.529 19.9646 14.6554C19.7783 14.0527 19.524 13.3501 19.2664 12.6751L18.3262 10.3168Z" fill="#0099FF"/>
</svg>
DSHQQBOT_F0_7c1e
cat > "$NM/@tencent-connect/dsh-qqbot/assets/icons/qqbot_logo.svg" <<'DSHQQBOT_F1_7c1e'
<svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
<path d="M19.3862 15.5001C19.3861 11.4203 16.0789 8.11296 11.999 8.11292C7.91915 8.11292 4.61203 11.4203 4.61182 15.5001V17.0001C4.61182 18.5949 5.90429 19.8873 7.49902 19.8873H16.499C18.0937 19.8873 19.3862 18.5949 19.3862 17.0001V15.5001ZM10.6118 14.0001C10.6118 14.6145 10.1129 15.1134 9.49853 15.1134C8.8843 15.1132 8.38672 14.6144 8.38672 14.0001V12.0006C8.38672 11.3863 8.8843 10.8875 9.49853 10.8873C10.1129 10.8873 10.6118 11.3862 10.6118 12.0006V14.0001ZM15.6113 14.0001C15.6113 14.6143 15.1136 15.1131 14.4995 15.1134C13.8851 15.1134 13.3862 14.6145 13.3862 14.0001V12.0006C13.3862 11.3862 13.8851 10.8873 14.4995 10.8873C15.1136 10.8876 15.6113 11.3864 15.6113 12.0006V14.0001ZM14.2607 3.04895C14.2607 3.89351 13.7957 4.62474 13.1108 5.0133V5.95374C17.8958 6.50514 21.6112 10.5676 21.6113 15.5001V17.0001C21.6113 19.8237 19.3225 22.1124 16.499 22.1124H7.49902C4.67546 22.1124 2.38672 19.8237 2.38672 17.0001V15.5001C2.38691 10.568 6.10139 6.50571 10.8857 5.95374V5.01185C10.2017 4.62305 9.73583 3.89286 9.73583 3.04895C9.73609 1.79961 10.7496 0.787231 11.999 0.787231C13.2484 0.787297 14.2605 1.79966 14.2607 3.04895Z" fill="#0085FF"/>
</svg>
DSHQQBOT_F1_7c1e
cat > "$NM/@tencent-connect/dsh-qqbot/cordis.patch.yml" <<'DSHQQBOT_F2_7c1e'
# dsh-im-qqbot bundle patch
#
# 当本包通过 `dsh plugin --profile <name> add @tencent-connect/dsh-qqbot` 安装后，
# dsh 启动时自动加载此 patch。
#
# 环境变量：
#   QQBOT_APPID  - QQ Bot AppID（必填）
#   QQBOT_SECRET - QQ Bot AppSecret（必填）
#
# 叠加顺序：dsh-base → 本 bundle patch → profile cordis.patch.yml → --patch

# ── 插入 im-qqbot 插件行 ──
- insert:
    - id: im-qqbot
      name: '@tencent-connect/dsh-qqbot'
      config:
        appId: __FROM_ENV__
        appSecret: __FROM_ENV__
        # provider/model 留空：从宿主默认模型路由继承
        # 用户可通过 /model 命令在聊天中切换
        requireMention: true
        textChunkLimit: 4500
        sessionIdleTimeout: 1800000
        maxQueue: 20
        processingTimeoutMs: 1800000
        historyLimit: 10
        debug: false
DSHQQBOT_F2_7c1e
cat > "$NM/@tencent-connect/dsh-qqbot/lib/client.js" <<'DSHQQBOT_F3_7c1e'
window.__ModuleLoader__.load({
	id: "@tencent-connect/dsh-qqbot",
	factory: (require) => {
		var module = { exports: {} };
		var exports = module.exports;
		Object.defineProperty(exports, Symbol.toStringTag, { value: "Module" });
		let react = require("react");
		//#region src/shared/bind-protocol.ts
		/**
		* 端内绑定协议 —— 宿主路由与客户端面板的共享契约
		*
		* 类型与路径常量的唯一事实源：宿主（setup/bind-routes.ts）与浏览器
		* （client/bind-page.ts）各自 import，杜绝两端协议漂移。
		* 本模块必须保持纯类型 + 纯常量（零 node 依赖、零副作用）：
		* 客户端 tsdown 构建会将其内联进 bundle。
		*/
		/** 状态查询（绑定页轮询） */
		const BIND_STATE_PATH = "/qqbot/im-qqbot/bind";
		/** 刷新二维码（绑定页按钮） */
		const BIND_REFRESH_PATH = "/qqbot/im-qqbot/bind/refresh";
		/** 手动填写/编辑凭据（绑定页表单） */
		const BIND_MANUAL_PATH = "/qqbot/im-qqbot/bind/manual";
		/** 解绑：移除已保存凭据，回到绑定流程 */
		const BIND_UNBIND_PATH = "/qqbot/im-qqbot/bind/unbind";
		/** 配置读写（设置面板表单） */
		const BIND_CONFIG_PATH = "/qqbot/im-qqbot/config";
		//#endregion
		//#region src/client/bind-page.ts
		/**
		* 端内绑定面板 — 扫码 / 手动填写 / 已绑定编辑
		*
		* 宿主插件注册 /qqbot/im-qqbot/bind 路由（待绑定与已绑定 fiber 均常驻）：
		* - 未绑定：waiting（二维码）/ starting / saving / failed 相位 + manual 提交
		* - 已绑定：bound 相位（回显脱敏 appId，secret 不回传）+ manual 更换 + 解绑
		* 扫码成功或手动保存均写入 profile patch 并经 HMR 重载生效。
		*
		* 样式为注入式 CSS 类（imqb-* 命名空间，随面板挂载注入一次）：
		* hover/过渡/focus 样式无法用 inline style 表达，统一走类；
		* 颜色尽量取 DSW 主题变量（--dsw-alias-*），缺省值兜底。
		*
		* 同一组件复用于两种展示位（侧栏绑定页 / 设置页 QQ Bot 栏目）。
		* 运行时仅依赖 react（dsh 客户端平台种子表提供）；宿主通信走同源 fetch，
		* Desktop 下由壳的 IPC 桥自动附加 Host 认证转发。
		*/
		/** 轮询间隔（毫秒）：活跃轮询 / 失败退避 */
		const ACTIVE_POLL_MS = 2e3;
		const RETRY_POLL_MS = 3e3;
		/** 样式注入标记（幂等） */
		const STYLE_ID$1 = "im-qqbot-bind-panel-styles";
		/**
		* 注入面板样式（全局一次，幂等）。交互态（hover/active/focus）无法用 inline
		* style 表达，统一收敛到类；DSW 主题变量缺失时用中性值兜底。
		* 插件激活时即安装：插件详情按钮渲染在面板之外，需提前可见；
		* 安装后不再随挂载移除，避免多个展示位互相清掉样式。
		*/
		function installPanelStyles() {
			if (typeof document === "undefined") return;
			if (document.getElementById(STYLE_ID$1) !== null) return;
			const style = document.createElement("style");
			style.id = STYLE_ID$1;
			style.textContent = `
.imqb-panel {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 14px; padding: 24px; min-height: 320px; text-align: center; font-size: 14px;
}
.imqb-title { margin: 0; font-size: 16px; font-weight: 600; }
.imqb-hint { margin: 0; opacity: 0.75; line-height: 1.6; }
.imqb-mono { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 13px; }
.imqb-link { font-size: 13px; opacity: 0.85; color: var(--dsw-alias-brand, #4d6bfe); text-decoration: none; }
.imqb-link:hover { text-decoration: underline; }
.imqb-icon { font-size: 32px; line-height: 1; }
.imqb-qr { border-radius: 10px; background: #fff; padding: 10px; max-width: 100%; }
.imqb-row { display: flex; gap: 10px; justify-content: center; flex-wrap: wrap; }
.imqb-btn, .imqb-pill {
  font: inherit; cursor: pointer; color: inherit;
  transition: background-color .15s ease, border-color .15s ease, color .15s ease, opacity .15s ease;
}
.imqb-btn:disabled, .imqb-pill:disabled { opacity: 0.5; cursor: default; }
.imqb-btn {
  padding: 7px 18px; border-radius: 8px; font-size: 13px;
  border: 1px solid var(--dsw-alias-border-l2, rgba(128, 128, 128, 0.4));
  background: transparent;
}
.imqb-btn:hover:not(:disabled) { background: var(--dsw-alias-interactive-bg-hover, rgba(128, 128, 128, 0.12)); }
.imqb-btn--primary {
  border-color: transparent;
  background: var(--dsw-alias-brand, #4d6bfe); color: #fff; font-weight: 500;
}
.imqb-btn--primary:hover:not(:disabled) { background: var(--dsw-alias-brand-strong, #3b5cf0); }
.imqb-btn--danger { color: var(--dsw-alias-danger, #f26d6d); border-color: var(--dsw-alias-danger, rgba(242, 109, 109, 0.5)); }
.imqb-btn--danger:hover:not(:disabled) { background: var(--dsw-alias-danger, rgba(242, 109, 109, 0.12)); }
.imqb-ghost {
  border: none; background: transparent; opacity: 0.65; padding: 4px 8px;
  font: inherit; font-size: 13px; cursor: pointer; color: inherit;
}
.imqb-ghost:hover { opacity: 1; text-decoration: underline; }
/* 插件详情「设置」按钮：30px，略高于旁边的 sm 次要按钮 */
.imqb-pluginOpen {
  display: inline-flex; align-items: center; justify-content: center;
  box-sizing: border-box; height: 30px; padding: 0 14px;
  border: 1px solid var(--dsw-alias-border-l2, rgba(128, 128, 128, 0.4));
  border-radius: 8px; background: var(--dsw-alias-bg-layer-1, transparent);
  color: var(--dsw-alias-label-primary, inherit); font: inherit;
  font-size: 13px; line-height: 20px; cursor: pointer;
}
.imqb-pluginOpen:hover { background: var(--dsw-alias-interactive-bg-hover, rgba(128, 128, 128, 0.12)); }
.imqb-pluginOpen:focus-visible { outline: 2px solid var(--dsw-alias-brand, #4d6bfe); outline-offset: 3px; }
@media (pointer: coarse) { .imqb-pluginOpen { height: 44px; } }
/* 主面板页面容器（layout.selectPanel 目标）：滚动 + 留白 */
.imqb-pluginPage {
  height: 100%; min-height: 0; overflow: auto; box-sizing: border-box;
  padding: 24px clamp(16px, 4vw, 48px) 32px;
  color: var(--dsw-alias-label-primary, #1f2329);
}
.imqb-pluginPageContent { max-width: 1080px; margin: 0 auto; }
.imqb-pill {
  padding: 5px 16px; border-radius: 999px; font-size: 13px;
  border: 1px solid var(--dsw-alias-border-l2, rgba(128, 128, 128, 0.4)); background: transparent;
}
.imqb-pill:hover:not(:disabled) { background: var(--dsw-alias-interactive-bg-hover, rgba(128, 128, 128, 0.12)); }
.imqb-btn:focus-visible, .imqb-pill:focus-visible, .imqb-input:focus-visible, .imqb-ghost:focus-visible {
  outline: 2px solid var(--dsw-alias-brand, #4d6bfe); outline-offset: 1px;
}
.imqb-form { display: flex; flex-direction: column; gap: 12px; width: min(320px, 100%); box-sizing: border-box; }
.imqb-field { display: flex; flex-direction: column; gap: 5px; text-align: left; font-size: 13px; }
.imqb-input {
  padding: 8px 10px; border-radius: 8px; box-sizing: border-box; width: 100%;
  border: 1px solid var(--dsw-alias-border-l2, rgba(128, 128, 128, 0.4));
  background: var(--dsw-alias-bg-input, rgba(128, 128, 128, 0.08));
  color: inherit; font: inherit; font-size: 13px; outline: none;
}
.imqb-input:focus { border-color: var(--dsw-alias-brand, #4d6bfe); }
.imqb-error { margin: 0; font-size: 12px; color: var(--dsw-alias-danger, #f26d6d); }
/* 紧凑状态视图（已绑定 / 过渡态）：设置行风格，无居中大卡留白 */
.imqb-status { display: flex; flex-direction: column; text-align: left; font-size: 14px; }
.imqb-status-row { display: flex; align-items: center; gap: 12px; padding: 12px 0; }
.imqb-status-icon { font-size: 24px; line-height: 1; flex: none; }
.imqb-qqicon {
  flex: none; display: block; border-radius: 8px; /* 透明底，QQ 蓝徽标在明暗主题下均清晰 */
}
.imqb-status-meta { display: flex; flex-direction: column; gap: 2px; min-width: 0; flex: 1; }
.imqb-status-title { margin: 0; font-size: 14px; font-weight: 600; line-height: 1.5; }
.imqb-status-sub { margin: 0; font-size: 12px; line-height: 1.5; color: var(--dsw-alias-label-tertiary, inherit); opacity: .85; }
.imqb-status-actions { display: flex; align-items: center; gap: 8px; padding: 4px 0 12px; }
/* 扫码成功后的连接过渡：二维码模糊变暗 + 覆盖层 */
.imqb-scanned { position: relative; display: inline-block; }
.imqb-scanned-qr {
  display: block; border-radius: 10px; background: #fff; padding: 10px;
  filter: blur(6px) saturate(0.6); opacity: 0.55;
}
.imqb-scanned-veil {
  position: absolute; inset: 0; display: flex; flex-direction: column;
  align-items: center; justify-content: center; gap: 6px; text-align: center;
}
.imqb-scanned-title { margin: 0; font-size: 15px; font-weight: 600; }
.imqb-scanned-sub { margin: 0; font-size: 12px; opacity: 0.75; line-height: 1.6; }
