        "11": "😡", "12": "🤗", "13": "⭐", "14": "🌟", "15": "🌙",
        "16": "👍", "18": "✊", "21": "😊", "23": "😢", "25": "🤔",
        "26": "😱", "27": "😅", "28": "😁", "29": "🤮", "30": "💪",
        "32": "🎉", "33": "😤", "34": "😏", "35": "🥺", "49": "🐷",
        "53": "🎂", "60": "☕", "63": "🌹", "66": "❤️", "74": "🌞",
