            try {
                const reply = format(e, ctx);
                if (reply) {
                    await ctx.bot.sendText(ctx.replyTarget, reply);
                }
            }
            catch (sendErr) {
                ctx.log.error?.(`[error-handler] failed to send error reply: ${sendErr instanceof Error ? sendErr.message : String(sendErr)}`);
