 */
export function verifyWebhookSignature(params) {
    const { body, timestamp, signature, botSecret } = params;
    try {
        const { publicKey } = getKeyPair(botSecret);
        const message = Buffer.concat([
            Buffer.from(timestamp, "utf-8"),
